import java.util.*;
public class Main {
  public static void main(String[] args) {
    Scanner s=new Scanner(System.in); int rows=s.nextInt(),cols=s.nextInt(); int[] a=new int[rows*cols]; for(int i=0;i<a.length;i++)a[i]=s.nextInt(); int x=s.nextInt(); int l=0,r=a.length-1; boolean ok=false; while(l<=r){int m=(l+r)/2; if(a[m]==x){ok=true;break;} if(a[m]<x)l=m+1;else r=m-1;} System.out.println(ok);
  }
}

